CREATE TABLE clientes (id_cliente NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR2(100) NOT NULL, telefono VARCHAR2(25), correo VARCHAR2(120));
CREATE TABLE mecanicos (id_mecanico NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR2(100) NOT NULL, telefono VARCHAR2(25), especialidad VARCHAR2(80) NOT NULL);
CREATE TABLE vehiculos (id_vehiculo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_cliente NUMBER NOT NULL REFERENCES clientes(id_cliente), placa VARCHAR2(15) NOT NULL UNIQUE, marca VARCHAR2(50) NOT NULL, modelo VARCHAR2(50) NOT NULL, anio NUMBER(4), descripcion VARCHAR2(200));
CREATE TABLE repuestos (id_repuesto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR2(100) NOT NULL, descripcion VARCHAR2(250), precio NUMBER(12,2) NOT NULL CHECK(precio>=0), existencia NUMBER(10) DEFAULT 0 NOT NULL CHECK(existencia>=0));
CREATE TABLE servicios (id_servicio NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, descripcion VARCHAR2(150) NOT NULL, costo_mano_obra NUMBER(12,2) NOT NULL CHECK(costo_mano_obra>=0));
CREATE TABLE ordenes_trabajo (id_orden NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_vehiculo NUMBER NOT NULL REFERENCES vehiculos(id_vehiculo), id_mecanico NUMBER NOT NULL REFERENCES mecanicos(id_mecanico), fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, problema VARCHAR2(1000) NOT NULL, estado VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL CHECK(estado IN ('PENDIENTE','EN PROCESO','FINALIZADA','CANCELADA')), total NUMBER(12,2) DEFAULT 0 NOT NULL CHECK(total>=0));
CREATE TABLE orden_servicios (id_orden NUMBER NOT NULL REFERENCES ordenes_trabajo(id_orden), id_servicio NUMBER NOT NULL REFERENCES servicios(id_servicio), costo_aplicado NUMBER(12,2) NOT NULL CHECK(costo_aplicado>=0), CONSTRAINT pk_orden_servicios PRIMARY KEY(id_orden,id_servicio));
CREATE TABLE orden_repuestos (id_orden NUMBER NOT NULL REFERENCES ordenes_trabajo(id_orden), id_repuesto NUMBER NOT NULL REFERENCES repuestos(id_repuesto), cantidad NUMBER(10) NOT NULL CHECK(cantidad>0), precio_aplicado NUMBER(12,2) NOT NULL CHECK(precio_aplicado>=0), CONSTRAINT pk_orden_repuestos PRIMARY KEY(id_orden,id_repuesto));
CREATE TABLE abastecimientos (id_abastecimiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_repuesto NUMBER NOT NULL REFERENCES repuestos(id_repuesto), cantidad NUMBER(10) NOT NULL CHECK(cantidad>0), fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
